#include <cuda_runtime.h>

#define TILE_SIZE 16
#define VEC_SIZE 4

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    int row = blockIdx.y * TILE_SIZE + threadIdx.y;
    int col = blockIdx.x * TILE_SIZE + threadIdx.x;

    float c_val = 0.0f;

    for (int t = 0; t < (N + TILE_SIZE - 1) / TILE_SIZE; t++) {
        // Load tile of A into shared memory using vectorized access
        int a_col = t * TILE_SIZE + threadIdx.x;
        if (row < N && a_col < N) {
            float4 a_vec = reinterpret_cast<const float4*>(&A[row * N + a_col])[0];
            As[threadIdx.y][threadIdx.x] = a_vec.x;
            if (threadIdx.x + 1 < TILE_SIZE && a_col + 1 < N) As[threadIdx.y][threadIdx.x+1] = a_vec.y;
            if (threadIdx.x + 2 < TILE_SIZE && a_col + 2 < N) As[threadIdx.y][threadIdx.x+2] = a_vec.z;
            if (threadIdx.x + 3 < TILE_SIZE && a_col + 3 < N) As[threadIdx.y][threadIdx.x+3] = a_vec.w;
        } else {
            As[threadIdx.y][threadIdx.x] = 0.0f;
        }

        // Load tile of B into shared memory using vectorized access
        int b_row = t * TILE_SIZE + threadIdx.y;
        if (b_row < N && col < N) {
            float4 b_vec = reinterpret_cast<const float4*>(&B[b_row * N + col])[0];
            Bs[threadIdx.y][threadIdx.x] = b_vec.x;
            if (threadIdx.y + 1 < TILE_SIZE && b_row + 1 < N) Bs[threadIdx.y+1][threadIdx.x] = b_vec.y;
            if (threadIdx.y + 2 < TILE_SIZE && b_row + 2 < N) Bs[threadIdx.y+2][threadIdx.x] = b_vec.z;
            if (threadIdx.y + 3 < TILE_SIZE && b_row + 3 < N) Bs[threadIdx.y+3][threadIdx.x] = b_vec.w;
        } else {
            Bs[threadIdx.y][threadIdx.x] = 0.0f;
        }

        __syncthreads();

        // Compute partial product
        for (int k = 0; k < TILE_SIZE; k++) {
            c_val += As[threadIdx.y][k] * Bs[k][threadIdx.x];
        }

        __syncthreads();
    }

    // Write result to global memory
    if (row < N && col < N) {
        C[row * N + col] = c_val;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "Inputs must be 2D matrices");
    TORCH_CHECK(A.size(1) == B.size(0), "Matrix dimensions incompatible for multiplication");

    int M = A.size(0);
    int N = A.size(1);
    int P = B.size(1);

    // Ensure matrix dimensions are multiples of VEC_SIZE for vectorization
    int padded_N = (N + VEC_SIZE - 1) / VEC_SIZE * VEC_SIZE;
