    dim3 blockSize(TILE_SIZE, TILE_SIZE);
    dim3 gridSize((padded_P + blockSize.x - 1) / blockSize.x, (M + blockSize.y - 1) / blockSize.y);

    // Launch kernel
    matmul_kernel<<<gridSize, blockSize>>>(A_padded.data_ptr<float>(), B_padded.data_ptr<float>(), C_padded.data_ptr<float>(), padded_N);

    // Return only the valid part of the result
    return C_padded.slice(1, 0, P);
}
